import{_ as t,o as e,c as r,a5 as d}from"./chunks/framework.bIR-4glx.js";const c=JSON.parse('{"title":"阅读地图：按问题进入","description":"按眼前的卡点进入《人生进阶指南》的七个入口、一张英语能力对照表和一条完整阅读弧线，帮助读者从问题而不是页码开始。","frontmatter":{"title":"阅读地图：按问题进入","description":"按眼前的卡点进入《人生进阶指南》的七个入口、一张英语能力对照表和一条完整阅读弧线，帮助读者从问题而不是页码开始。","updated":"2026-11-23T00:00:00.000Z"},"headers":[],"relativePath":"reference/reading-map.md","filePath":"reference/reading-map.md","lastUpdated":1795392000000}'),h={name:"reference/reading-map.md"};function i(s,a,n,l,o,p){return e(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="阅读地图-按问题进入" tabindex="-1">阅读地图：按问题进入 <a class="header-anchor" href="#阅读地图-按问题进入" aria-label="Permalink to &quot;阅读地图：按问题进入&quot;">​</a></h1><p>这张地图回答一个具体问题：<strong>我现在最需要看清什么、完成什么，或停止什么？</strong> 先找到与你此刻最接近的一格，读完一节就暂停，做一个小动作，再决定下一页。</p><h2 id="先选择今天的入口" tabindex="-1">先选择今天的入口 <a class="header-anchor" href="#先选择今天的入口" aria-label="Permalink to &quot;先选择今天的入口&quot;">​</a></h2><h3 id="我只是想重新开始" tabindex="-1">我只是想重新开始 <a class="header-anchor" href="#我只是想重新开始" aria-label="Permalink to &quot;我只是想重新开始&quot;">​</a></h3><p>先读<a href="./../threads/part-0/prologue">序章：先不要急着改变人生</a>，再打开<a href="./../templates/learning-state">学习状态模板</a>。如果今天只有五分钟，只写下真实问题、手边已有的线索、一个最小动作和必须守住的边界；不必先设计三年计划。</p><h3 id="我想提高一项具体的英语能力" tabindex="-1">我想提高一项具体的英语能力 <a class="header-anchor" href="#我想提高一项具体的英语能力" aria-label="Permalink to &quot;我想提高一项具体的英语能力&quot;">​</a></h3><p>先从<a href="./../threads/part-1/0-cefr">CEFR 目标与自测</a>确认场景和起点，再从下面选一条主线。一次只选一项，留下首版和对应的<a href="./glossary#工具与交付">证据卡</a>，不要让“想全部学会”替你推迟开始。</p><table tabindex="0"><thead><tr><th>眼前的障碍</th><th>进入章节</th><th>留下的第一份样本</th></tr></thead><tbody><tr><td>生词很多，不知道哪些值得查</td><td><a href="./../threads/part-1/2-vocabulary">词汇篇</a> · <a href="./../templates/vocabulary-audit">词汇证据卡</a></td><td>一张未知项决定与无提示调用记录</td></tr><tr><td>规则似乎懂了，表达却改变了时间、责任或确定性</td><td><a href="./../threads/part-1/grammar">语法篇</a> · <a href="./../templates/grammar-evidence">语法证据卡</a></td><td>一项高影响结构的前后对照</td></tr><tr><td>收藏了很多音频，仍然只能靠字幕理解</td><td><a href="./../threads/part-1/3-listening">听力篇</a> · <a href="./../templates/listening-audit">听力证据卡</a></td><td>首听记录、错误地图和一次平行迁移</td></tr><tr><td>技术文档读得慢，读完却不能交付</td><td><a href="./../threads/part-1/4-reading">阅读篇</a> · <a href="./../templates/reading-evidence">阅读证据卡</a></td><td>一张主张、证据与最小技术事实清单</td></tr><tr><td>只在背熟稿件里流畅，遇到追问就退出</td><td><a href="./../threads/part-1/5-speaking">口语篇</a> · <a href="./../templates/speaking-evidence">口语证据卡</a></td><td>一次听众复述、互动修复或陌生问题回应</td></tr><tr><td>写不出自己的初稿，只能展示 AI 润色后的成品</td><td><a href="./../threads/part-1/6-writing">写作篇</a> · <a href="./../templates/writing-evidence">写作证据卡</a></td><td>一份无辅助初稿、事实来源和修改理由</td></tr></tbody></table><p>学得更多不等于学得更深；能够在新场景中完成，能力才开始显形。</p><h3 id="我正在准备海外岗位或远程面试" tabindex="-1">我正在准备海外岗位或远程面试 <a class="header-anchor" href="#我正在准备海外岗位或远程面试" aria-label="Permalink to &quot;我正在准备海外岗位或远程面试&quot;">​</a></h3><p>先读<a href="./../threads/part-1/8-job-search-english">求职英语篇：把能力带进面试与远程协作</a>，不要先用一个 CEFR 标签决定自己是否“够格”。选择一个真实岗位，用<a href="./../templates/interview-evidence">求职英语证据卡</a>保存无稿项目说明、陌生追问、异步更新和修复动作，再决定是投递、补一个高风险缺口，还是暂缓。</p><h3 id="我有很多资料-却没有作品" tabindex="-1">我有很多资料，却没有作品 <a class="header-anchor" href="#我有很多资料-却没有作品" aria-label="Permalink to &quot;我有很多资料，却没有作品&quot;">​</a></h3><p>先看<a href="./../threads/part-3/1-ai-learning">使用 AI 学习一切</a>，把问题、来源、隐私边界和人工判断写进<a href="./../templates/ai-task-brief">AI 任务简报</a>，再用<a href="./../templates/artifact-brief">作品简报与交付卡</a>写清受众、完成标准、验收人和回滚方式。聊天记录可以帮助你开始，不能替你交付。</p><h3 id="我有很多记录-却不知道自己是否真的改变" tabindex="-1">我有很多记录，却不知道自己是否真的改变 <a class="header-anchor" href="#我有很多记录-却不知道自己是否真的改变" aria-label="Permalink to &quot;我有很多记录，却不知道自己是否真的改变&quot;">​</a></h3><p>打开<a href="./../templates/evidence-chain">证据链模板</a>，把基线、即时表现、延迟保持和迁移放在同一页，再回到<a href="./../threads/part-3/5-evidence-and-transfer">证据篇：变化要如何被看见</a>区分已经得到支持的结论和仍待检验的解释。若不知道该选哪张工作纸，先看<a href="./../templates/toolkit-walkthrough">工具箱实战</a>，再回到<a href="./../templates/toolkit">工具箱总览</a>按眼前的卡点选择一个入口。</p><h3 id="我正在帮助一名初中阶段的学习者" tabindex="-1">我正在帮助一名初中阶段的学习者 <a class="header-anchor" href="#我正在帮助一名初中阶段的学习者" aria-label="Permalink to &quot;我正在帮助一名初中阶段的学习者&quot;">​</a></h3><p>先读<a href="./../threads/part-4/family-learning">家庭学习篇：把成长还给孩子</a>，不要把成人的时间管理、职业项目和 AI 账户前提直接套给孩子。用<a href="./../templates/family-learning-agreement">家庭学习共同协议</a>分别写下孩子的目标、家长的担心、学校要求、数据边界和复查时间；孩子先说，成人负责安全与环境，不代做也不全天监控。</p><h3 id="我正在低谷-今天的容量很小" tabindex="-1">我正在低谷，今天的容量很小 <a class="header-anchor" href="#我正在低谷-今天的容量很小" aria-label="Permalink to &quot;我正在低谷，今天的容量很小&quot;">​</a></h3><p>先读<a href="./../threads/part-2/recovery">恢复篇：先把自己接住</a>和<a href="./../threads/part-4/daily-system">生活系统篇</a>。今天的目标可以只是安全、吃饭、睡眠、求助和暂停；这些本身就值得被认真对待，不必为了证明自己还在前进而勉强交出一个漂亮的输出。若低落、失眠、绝望或危险念头持续存在，优先联系可信的人并寻求当地合格的医疗或心理专业支持；本书不能替代照护。</p><h2 id="一条完整的阅读弧线" tabindex="-1">一条完整的阅读弧线 <a class="header-anchor" href="#一条完整的阅读弧线" aria-label="Permalink to &quot;一条完整的阅读弧线&quot;">​</a></h2><p>完整阅读不是把页码走完，而是让同一个问题经过几次变化：先看见自己，再回到生活，重新学习，借工具放大能力，最后把节奏交给时间。</p><table tabindex="0"><thead><tr><th>阶段</th><th>阅读范围</th><th>读完留下什么</th></tr></thead><tbody><tr><td>看见起点</td><td><a href="./../threads/part-0/prologue">序章</a> · <a href="./../threads/part-2/my-story">我的故事</a></td><td>一页读者承诺：真实问题、基线、最小动作和边界</td></tr><tr><td>回到生活</td><td><a href="./../threads/part-2/recovery">恢复</a> · <a href="./../threads/part-2/decision">选择</a> · <a href="./../threads/part-2/relationships">关系</a></td><td>三项可确认的事实、一项要承担的责任、一个边界</td></tr><tr><td>重新学习</td><td><a href="./../threads/part-1/0-cefr">CEFR 自测</a> 与词汇、语法、听、读、说、写章节</td><td>一份<a href="./../templates/english-diagnostic">英语能力诊断</a>和一张对应的<a href="./glossary#工具与交付">证据卡</a></td></tr><tr><td>放大能力</td><td><a href="./../threads/part-3/1-ai-learning">使用 AI 学习一切</a> · <a href="./../threads/part-3/4-artifacts-and-delivery">作品篇</a> · <a href="./../threads/part-3/5-evidence-and-transfer">证据篇</a></td><td>一次可复查的小实验和一份真实交付</td></tr><tr><td>实践与交付</td><td><a href="./../threads/part-4/week-1">第一周实践</a> · <a href="./../threads/part-5/90-day-plan">九十天行动篇</a> · <a href="./../threads/part-6/1-understanding-yourself">与自己做终身朋友</a></td><td>一份第一周基线、一页<a href="./../templates/rhythm-ledger">节律账本</a>、一次真实项目交接和下一次复查日期</td></tr></tbody></table><h2 id="每一章都留下四种痕迹" tabindex="-1">每一章都留下四种痕迹 <a class="header-anchor" href="#每一章都留下四种痕迹" aria-label="Permalink to &quot;每一章都留下四种痕迹&quot;">​</a></h2><p>读完一个章节，不要只标记“已读”。请至少留下下面四项中的两项：</p><table tabindex="0"><thead><tr><th>痕迹</th><th>要回答的问题</th><th>例子</th></tr></thead><tbody><tr><td>一个判断</td><td>我现在比读之前更确定什么？</td><td>“这周只追踪一个主问题。”</td></tr><tr><td>一个样本</td><td>什么输出能证明我做过？</td><td>一段录音、一封邮件、一张错误清单</td></tr><tr><td>一个边界</td><td>哪些事不能交给工具或想象？</td><td>不上传客户隐私；不把单一经历写成规律</td></tr><tr><td>一个回访点</td><td>什么时候用什么条件复测？</td><td>七天后换主题重做同一任务</td></tr></tbody></table><p>如果一章读完只留下了“很有道理”，先不要继续收藏。把它改写成一项可以被别人看见、被自己复查的动作。</p><h2 id="回到阅读指南" tabindex="-1">回到阅读指南 <a class="header-anchor" href="#回到阅读指南" aria-label="Permalink to &quot;回到阅读指南&quot;">​</a></h2><p>这张地图只负责指出入口。关于怎样安排一次完整阅读、怎样在中断后回来，以及这本书不替你做什么，请看<a href="./../threads/part-0/reader-guide">如何读这本书</a>。如果你今天只想做一件事，打开<a href="./../templates/learning-state">学习状态模板</a>，写下问题、线索、最小动作和边界。</p>',28)])])}const m=t(h,[["render",i]]);export{c as __pageData,m as default};
